export type QueryKey<TOptions extends Options> = [
  Pick<TOptions, 'baseUrl' | 'body' | 'headers' | 'path' | 'query'> & {
    _id: string;
    _infinite?: boolean;
    tags?: ReadonlyArray<string>;
  },
];

const createQueryKey = <TOptions extends Options>(
  id: string,
  options?: TOptions,
  infinite?: boolean,
  tags?: ReadonlyArray<string>,
): [QueryKey<TOptions>[0]] => {
  const params: QueryKey<TOptions>[0] = {
    _id: id,
    baseUrl: options?.baseUrl || (options?.client ?? client).getConfig().baseUrl,
  } as QueryKey<TOptions>[0];
  if (infinite) {
    params._infinite = infinite;
  }
  if (tags) {
    params.tags = tags;
  }
  if (options?.body) {
    params.body = options.body;
  }
  if (options?.headers) {
    params.headers = options.headers;
  }
  if (options?.path) {
    params.path = options.path;
  }
  if (options?.query) {
    params.query = options.query;
  }
  return [params];
};

export const healthControllerCheckQueryKey = (options?: Options<HealthControllerCheckData>) =>
  createQueryKey('healthControllerCheck', options);

/**
 * Liveness check
 */
export const healthControllerCheckOptions = (options?: Options<HealthControllerCheckData>) =>
  queryOptions<
    HealthControllerCheckResponse,
    DefaultError,
    HealthControllerCheckResponse,
    ReturnType<typeof healthControllerCheckQueryKey>
  >({
    queryFn: async ({ queryKey, signal }) => {
      const { data } = await Health.healthControllerCheck({
        ...options,
        ...queryKey[0],
        signal,
        throwOnError: true,
      });
      return data;
    },
    queryKey: healthControllerCheckQueryKey(options),
  });

/**
 * Send registration OTP (email)
 *
 * Starts email-based registration for a **new** member. Proxies to the Yamauchi API, which creates an inactive user and emails a 6-digit OTP. Confirm it via `POST /auth/email/confirm`. Public endpoint.
 *
 * If the email already belongs to a registered account, Yamauchi rejects it with `E-AUTH-020` (409). Too many requests (Yamauchi throttles OTP sends) → `E-RATE-001` (429). A Yamauchi outage surfaces as `E-EXT-001` / `E-EXT-002` (502).
 */
export const emailOtpControllerRegisterMutation = (
  options?: Partial<Options<EmailOtpControllerRegisterData>>,
): UseMutationOptions<
  EmailOtpControllerRegisterResponse,
  EmailOtpControllerRegisterError,
  Options<EmailOtpControllerRegisterData>
> => {
  const mutationOptions: UseMutationOptions<
    EmailOtpControllerRegisterResponse,
    EmailOtpControllerRegisterError,
    Options<EmailOtpControllerRegisterData>
  > = {
    mutationFn: async (fnOptions) => {
      const { data } = await AuthEmailOtp.emailOtpControllerRegister({
        ...options,
        ...fnOptions,
        throwOnError: true,
      });
      return data;
    },
  };
  return mutationOptions;
};

